188	export function decideValidationOutcome(input: ValidationInput): ValidationOutcome {
189	  const { conclusion, reviewerAgent, engineerAgent } = input;
190	
191	  // Judged first, and treated as the red CI run it stands in for: failing checks so
192	  // the merge is blocked, a comment so whoever acts next has the problems at once.
193	  // Nobody is dispatched — the pull request's own agent is named in the mention
194	  // instead, and a person asks for the fix. Failing the workflow step instead would
195	  // have written no check at all, which leaves the required context pending forever
196	  // — a pull request only a human can rescue, for a mistake an agent makes in the
197	  // ordinary course of editing its own tool surface.
198	  const deliverableProblems = input.deliverableProblems ?? [];
199	  if (deliverableProblems.length > 0) {
200	    const count = `${deliverableProblems.length} problem${deliverableProblems.length === 1 ? "" : "s"}`;
201	    return {
202	      verdict: "deliverable-invalid",
203	      summary:
204	        `.github/atomaton/ is not internally consistent (${count}), so CI was not run.` +
205	        `${askFor(engineerAgent)}`,
206	    };
207	  }
208	
209	  const normalised = conclusion.trim().toLowerCase();
210	  const passed = PASSING.has(normalised);
211	
212	  if (passed) {
213	    // The hold is the whole gate. A green verdict starts the standing request only
214	    // where a call is waiting for it: the ball with nobody yet, an ask nobody has
215	    // taken up, or the park whose collection this validation is. Everywhere else --
216	    // a run in flight (its own report is the thread's next word), a chain that
217	    // already carries the call, a turn a run handed back to a person -- the verdict
218	    // is delivered as a mention, and the person decides. This is the rule the
219	    // re-ask-the-asker routing replaced: a green run there re-started whoever made
220	    // the newest ask, call or no call, and its report was still being written when
221	    // the machinery started the next run over it.
222	    const hold = input.hold ?? { kind: "with-person" as const };
223	    if (hold.kind === "free" || hold.kind === "parked") {
224	      return { verdict: "passed", ...handTo(reviewerAgent), summary: `CI concluded ${normalised}.` };
225	    }
226	    const because: Record<string, string> = {
227	      "in-flight": "a run already holds this pull request, and its own report is the thread's next word",
228	      chain: "the thread's newest word handed the work to another agent, and that call is the chain's to carry",
229	      "with-person": "the thread's newest word handed the turn back to a person",
230	      unreadable: "the thread could not be read to rule out a run in flight",
231	    };
232	    return {
233	      verdict: "passed",
234	      summary:
235	        `CI concluded ${normalised}, and nothing was dispatched: ${because[hold.kind] ?? because["with-person"]}.` +
236	        `${reviewerAgent.trim() === "" ? "" : ` Comment /${reviewerAgent.trim()} to start the review yourself.`}`,
237	    };
238	  }
239	
240	  if (!normalised) {
241	    return {
242	      verdict: "no-conclusion",
243	      summary: "CI never reported a conclusion. Nothing was dispatched; a human should look.",
244	    };
245	  }
246	
247	  // Red, and nobody is dispatched. The engineer who opened the pull request is the
248	  // one who made the change, so the mention names it and the person asks for the
249	  // fix; the failing-run URL and the checks ride on the comment this verdict's
250	  // caller posts. The automatic retry this replaced started the opener without a
251	  // call, on a verdict nobody had asked it to act on.
252	  return {
253	    verdict: "failed",
254	    summary:
255	      `CI concluded ${normalised}. Nobody was dispatched to fix it.` +
256	      `${askFor(engineerAgent)}`,
257	  };
258	}

