1	#!/usr/bin/env bun
2	/**
3	 * notify_unattended.ts — tell a person that a pull request's validation finished
4	 * and nobody was dispatched.
5	 *
6	 * ## Why this is a step of its own
7	 *
8	 * The validation writes a check run and, when it can, dispatches an agent. When it
9	 * cannot, the check is still written and the work simply waits -- and a pull
10	 * request that waits unannounced is the failure this exists to prevent. It is the
11	 * same failure `unattendedNotice` covers at creation time, one round later: the
12	 * pull request was attended when it was opened, and the agent it named is not
13	 * coming because CI failed and the request came from a person.
14	 *
15	 * ## Who is told
16	 *
17	 * `resolveNotify`, which is the person who asked for the run -- the commenter for a
18	 * comment, the opener for an issue, and the repository owner as a last resort. It
19	 * is the same resolution every other notice uses, so a person who is told about a
20	 * failure here is the person who was told about the run starting.
21	 *
22	 * Usage:
23	 *   notify_unattended.ts --repo OWNER/REPO --number N --summary "..."
24	 */
25	import { parseArgs } from "node:util";
26	import { gh } from "../../adapters/github/gh.ts";
27	import { resolveNotify } from "../../adapters/github/notify.ts";
28	import { LLM_CONTEXT_TAG } from "../../adapters/github/tags.ts";
29	import { mentionPrefix } from "../../domain/work/mention.ts";
30	import { defineScript } from "./lib/script-ref.ts";
31	
32	export interface NotifyUnattendedArgs {
33	  repo: string;
34	  number: string | number;
35	  summary: string;
36	}
37	
38	export const ref = defineScript<NotifyUnattendedArgs>(import.meta.url);
39	
40	function main(): void {
41	  const { values } = parseArgs({
42	    args: Bun.argv.slice(2),
43	    options: {
44	      repo: { type: "string" },
45	      number: { type: "string" },
46	      summary: { type: "string" },
47	    },
48	  });
49	
50	  const repo = values.repo ?? "";
51	  const number = values.number ?? "";
52	  if (!repo || !number) {
53	    console.error("usage: notify_unattended.ts --repo OWNER/REPO --number N --summary \"...\"");
54	    process.exit(2);
55	  }
56	
57	  const notify = resolveNotify(repo, Number(number));
58	  const mention = mentionPrefix(notify);
59	  const summary = (values.summary ?? "").trim();
60	
61	  // Tagged `include`, deliberately. This is a fact about the pull request -- that
62	  // its validation finished and nobody is coming -- and a later agent reading the
63	  // thread should see it. The bookkeeping comments are the ones that are excluded.
64	  const body = [
65	    LLM_CONTEXT_TAG.write("include"),
66	    `${mention}Atomaton: validation of this pull request finished and no agent was dispatched.`,
67	    ...(summary ? ["", summary] : []),
68	    "",
69	    "Comment `/<agent>` on this pull request to start one, or merge it yourself.",
70	  ].join("\n");
71	
72	  const posted = gh("pr", "comment", String(number), "--repo", repo, "--body", body);
73	  if (posted.code) {
74	    console.error(`::warning::could not post the unattended notice on #${number}: ${posted.stderr.trim()}`);
75	  }
76	}
